+        this.messageStore = messageStore;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        messages.addColumn(SentMessage::name).setHeader("Name");
+        messages.addColumn(SentMessage::message).setHeader("Message");
