+        phone.addValueChangeListener(event -> formWasEdited());
+        message.addValueChangeListener(event -> formWasEdited());
+
+        add(name, email, phone, message, send, messages);
+    }
+
+    private void formWasEdited() {
+        if (!resettingForm) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        clearValidation();
+        if (!isValidForm()) {
+            return;
+        }
+
+        messageStore.add(new SentMessage(name.getValue(), email.getValue(),
+                phone.getValue(), message.getValue()));
+        messages.setItems(messageStore.all());
+        resetForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValidForm() {
+        boolean valid = true;
+        if (name.getValue().isBlank()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+        if (!email.getValue().isBlank() && !isEmailAddress(email.getValue())) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        }
+        if (email.getValue().isBlank() && phone.getValue().isBlank()) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (message.getValue().isBlank()) {
+            invalidate(message, "Message is required");
+            valid = false;
